import heapq


def solve(dependencies):
    # Collect all nodes (keys + nodes appearing only as prerequisites)
    all_nodes = set()
    for node, prereqs in dependencies.items():
        all_nodes.add(node)
        for p in prereqs:
            all_nodes.add(p)

    # Build adjacency list and in-degree count, ignoring duplicate edges
    adj = {n: [] for n in all_nodes}
    in_degree = {n: 0 for n in all_nodes}

    for node, prereqs in dependencies.items():
        seen = set()
        for p in prereqs:
            if p not in seen:
                seen.add(p)
                adj[p].append(node)
                in_degree[node] += 1

    # Kahn's algorithm, always picking the lexicographically smallest ready node
    heap = [n for n in all_nodes if in_degree[n] == 0]
    heapq.heapify(heap)

    result = []
    while heap:
        node = heapq.heappop(heap)
        result.append(node)
        for neighbor in adj[node]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                heapq.heappush(heap, neighbor)

    if len(result) != len(all_nodes):
        return None

    return result
