from collections import deque


def solve(dependencies, changed):
    # Build reverse dependency graph: prerequisite -> list of dependents
    reverse = {}
    for service, prereqs in dependencies.items():
        for prereq in prereqs:
            if prereq not in reverse:
                reverse[prereq] = []
            reverse[prereq].append(service)

    # BFS from all changed services through reverse edges
    visited = set(changed)
    queue = deque(changed)

    while queue:
        current = queue.popleft()
        for dependent in reverse.get(current, []):
            if dependent not in visited:
                visited.add(dependent)
                queue.append(dependent)

    return sorted(visited)
