import math


def solve(replicas, unavailable, surge):
    def _valid_int(value):
        """Check if value is a valid nonnegative integer (not a bool)."""
        if isinstance(value, bool):
            return False
        if not isinstance(value, int):
            return False
        if value < 0:
            return False
        return True

    def _parse(value, replicas, rounding):
        """Parse a count or percentage string to a count.
        rounding: 'floor' for unavailable, 'ceil' for surge.
        Returns None if invalid.
        """
        if isinstance(value, bool):
            return None

        if isinstance(value, int):
            if value < 0:
                return None
            return value

        if isinstance(value, str):
            if not value.endswith('%'):
                return None
            number_part = value[:-1]
            if not number_part or not number_part.isdigit():
                return None
            pct = int(number_part)
            if pct < 0 or pct > 100:
                return None
            product = pct * replicas
            if rounding == 'floor':
                return product // 100
            else:  # ceil
                return -(-product // 100)

        return None

    # Validate replicas
    if not _valid_int(replicas):
        return None

    # Parse unavailable and surge
    u = _parse(unavailable, replicas, 'floor')
    if u is None:
        return None

    s = _parse(surge, replicas, 'ceil')
    if s is None:
        return None

    return {"unavailable": u, "surge": s}
