        return None

    # Validate that timestamps are strictly increasing
    for i in range(1, len(samples)):
        if samples[i][0] <= samples[i - 1][0]:
            return None

    total_increase = 0

    for i in range(1, len(samples)):
        prev_counter = samples[i - 1][1]
        curr_counter = samples[i][1]
        if curr_counter >= prev_counter:
            total_increase += curr_counter - prev_counter
        else:
            # Reset: contribute the new counter value
            total_increase += curr_counter

