def solve(text):
    import ipaddress

    if not text:
        return None

    if any(c.isspace() for c in text):
        return None

    if text.startswith('['):
        # IPv6 format: [addr]:port
        bracket_end = text.find(']')
        if bracket_end == -1:
            return None
        addr_str = text[1:bracket_end]
        rest = text[bracket_end + 1:]
        if not rest.startswith(':'):
            return None
        port_str = rest[1:]

        # Reject zone identifiers
        if '%' in addr_str:
            return None

        # Validate port
        if not port_str or not all(c in '0123456789' for c in port_str):
            return None
        port = int(port_str)
        if port < 1 or port > 65535:
            return None

        # Validate IPv6
        try:
            addr = ipaddress.IPv6Address(addr_str)
        except ValueError:
            return None

        return {"address": str(addr), "port": port}
    else:
        # IPv4 format: addr:port
        colon_pos = text.rfind(':')
        if colon_pos == -1:
            return None
        addr_str = text[:colon_pos]
        port_str = text[colon_pos + 1:]

        # Validate port
        if not port_str or not all(c in '0123456789' for c in port_str):
            return None
        port = int(port_str)
        if port < 1 or port > 65535:
            return None

        # Validate IPv4: strict dotted-quad, no leading zeros
        parts = addr_str.split('.')
        if len(parts) != 4:
            return None
        for part in parts:
            if not part or not all(c in '0123456789' for c in part):
                return None
            if len(part) > 1 and part[0] == '0':
                return None
            if int(part) > 255:
                return None

        return {"address": addr_str, "port": port}
