def solve(text):
    after = []
    wants = []
    in_unit = False

    for line in text.split('\n'):
        stripped = line.strip()

        # Skip blank lines and full-line comments
        if not stripped or stripped.startswith('#') or stripped.startswith(';'):
            continue

        # Section headers
        if stripped.startswith('[') and stripped.endswith(']'):
            in_unit = (stripped == '[Unit]')
            continue

        # Ignore keys outside [Unit]
        if not in_unit:
            continue

        # Parse key=value
        if '=' not in stripped:
            continue

        key, value = stripped.split('=', 1)
        key = key.strip()
        value = value.strip()

        if key == 'After':
            if value == '':
                after.clear()
            else:
                for item in value.split():
                    if item not in after:
                        after.append(item)
        elif key == 'Wants':
            if value == '':
                wants.clear()
            else:
                for item in value.split():
                    if item not in wants:
                        wants.append(item)

    return {"After": after, "Wants": wants}
