def solve(hostname, patterns):
    # Remove one optional trailing dot from hostname
    if hostname.endswith('.'):
        hostname = hostname[:-1]
    hostname_lower = hostname.lower()

    for pattern in patterns:
        # Remove one optional trailing dot from pattern
        if pattern.endswith('.'):
            pattern = pattern[:-1]
        pattern_lower = pattern.lower()

        if pattern_lower.startswith('*.'):
            # Valid wildcard form: *.suffix
            suffix = pattern_lower[2:]

            # Suffix must be non-empty and contain no asterisks (other asterisks are invalid)
            if not suffix or '*' in suffix:
                continue

            # Hostname must end with "." + suffix, and the part before must be
            # exactly one nonempty label (no dots, not empty)
            if hostname_lower.endswith('.' + suffix):
                prefix = hostname_lower[:-(len(suffix) + 1)]
                if prefix and '.' not in prefix:
                    return True
        else:
            # Exact match — any other asterisk in pattern is invalid, skip
            if '*' in pattern_lower:
                continue
            if hostname_lower == pattern_lower:
                return True

    return False
